pub type __uint8_t = u8;
pub type uint8_t = __uint8_t;
pub type byte = uint8_t;
pub type fixed_t = i32;
pub type angle_t = u32;
pub const FINEANGLES: i32 = 8192 as i32;
pub const SLOPERANGE: i32 = 2048 as i32;
pub fn SlopeDiv(
    mut num: u32,
    mut den: u32,
) -> i32 {
    let mut ans: u32 = 0;
    if den < 512 as u32 {
        return SLOPERANGE
    } else {
        ans = (num << 3 as i32)
            .wrapping_div(den >> 8 as i32);
        if ans <= SLOPERANGE as u32 {
            return ans as i32
        } else {
            return SLOPERANGE
        }
    };
}
